  const [busy, setBusy] = useState(false); const [message, setMessage] = useState(""); const [error, setError] = useState("");
  const reset = () => { setEditing(null); setName(""); setContact(""); setTelegramUserId(""); setTelegramUsername(""); setNotes(""); setMessage(""); setError(""); };
  const beginEdit = (customer: Customer) => { setEditing(customer); setName(customer.name); setContact(customer.contact ?? ""); setTelegramUserId(customer.telegram_user_id ?? ""); setTelegramUsername(customer.telegram_username ?? ""); setNotes(customer.notes ?? ""); setError(""); setMessage(""); };
